#ifndef MOTOR_CONTROL_H
#define MOTOR_CONTROL_H

#include <stdint.h>
#include "pid.h"


typedef struct
{
    /*
     * PID controller object.
     */
    PID_t pid;


    /*
     * Desired motor speed.
     */
    float target_rpm;


    /*
     * Measured motor speed.
     */
    float actual_rpm;


    /*
     * PWM command generated by PID.
     *
     * Range:
     * 0% → 100%
     */
    float pwm_percent;


    /*
     * Previous encoder counter value.
     */
    uint16_t previous_encoder;

} MotorController_t;


/*
 * Initialize motor controller.
 */
void MotorController_Init(MotorController_t *motor);


/*
 * Set desired motor speed.
 */
void MotorController_SetTarget(MotorController_t *motor,
                                float rpm);


/*
 * Execute one motor-control update.
 */
void MotorController_Update(MotorController_t *motor,
                            uint16_t encoder_count,
                            float dt);

#endif
